import socket


class IpUtil:
    _AF_INET = socket.AF_INET
    _AF_INET6 = socket.AF_INET6

    @staticmethod
    def is_valid_ipv4(ip_address):
        return IpUtil._validate_ip(ip_address, IpUtil._AF_INET)

    @staticmethod
    def is_valid_ipv6(ip_address):
        return IpUtil._validate_ip(ip_address, IpUtil._AF_INET6)

    @staticmethod
    def _validate_ip(ip_address, address_family):
        try:
            socket.inet_pton(address_family, ip_address)
            return True
        except socket.error:
            return False

    @staticmethod
    def get_hostname(ip_address):
        try:
            return socket.gethostbyaddr(ip_address)[0]
        except socket.herror:
            return None
